// --- S-06: elapsed-time warning ---

#[test]
fn s06_slow_outcome_verify_warning_emits_at_threshold() {
    let msg = residual::verify::slow_outcome_verify_warning(std::time::Duration::from_secs(2));
    assert!(
        msg.is_some(),
        "expected slow-verify warning at 2s threshold"
    );
    let text = msg.unwrap();
    assert!(text.contains("WARN"), "got: {text}");
    assert!(text.contains("2"), "should mention threshold; got: {text}");
}

#[test]
fn s06_slow_outcome_verify_warning_silent_below_threshold() {
    let msg = residual::verify::slow_outcome_verify_warning(std::time::Duration::from_millis(500));
    assert!(msg.is_none());
}

